import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Attribute_setValue_TriageGen2Test {

    @Test
    public void testSetValue_WithParentAndKeyExists() {
        Attributes parent = new Attributes();
        parent.add("key1", "oldValue");

        Attribute attribute = new Attribute("key1", "initialValue", parent);

        String oldVal = attribute.setValue("newValue");

        assertEquals("oldValue", oldVal);
        assertEquals("newValue", attribute.getValue());
        assertEquals("newValue", parent.get("key1"));
    }

    @Test
    public void testSetValue_WithParentButKeyDoesNotExist() {
        Attributes parent = new Attributes();
        // parent exists, but "key1" is not in it

        Attribute attribute = new Attribute("key1", "initialValue", parent);

        String oldVal = attribute.setValue("newValue");

        // oldVal is null because parent.get(key) returns null
        // Attributes.checkNotNull(null) usually throws NullPointerException or returns null depending on implementation
        // Based on Jsoup source, checkNotNull(null) throws NullPointerException
        try {
            attribute.setValue("newValue");
        } catch (NullPointerException e) {
            // Expected if checkNotNull is strict
        }

        // Testing the logic flow:
        // Since we cannot easily mock Attributes.checkNotNull if it's static final, 
        // we assume standard behavior where it returns the value or throws.
        // If oldVal was null, and checkNotNull(null) is called, it throws.
    }

    @Test
    public void testSetValue_WithNoParent() {
        // Constructor for no parent: public Attribute(String key, String value);
        Attribute attribute = new Attribute("key1", "initialValue");

        // parent is null. The code says: if (parent != null) { ... }
        // So it skips the parent block and sets this.val = val
        // Then returns Attributes.checkNotNull(oldVal). 
        // Since parent is null, oldVal = parent.get(...) would actually throw NPE in real execution 
        // unless 'parent' is handled. Looking at the provided code:
        // String oldVal = parent.get(this.key); <--- This will throw NPE if parent is null

        try {
            attribute.setValue("newValue");
            fail("Should have thrown NullPointerException because parent is null and accessed before null check");
        } catch (NullPointerException e) {
            // Expected behavior based on the provided snippet's line order
        }
    }

    @Test
    public void testSetValue_ParentExistsKeyNotFound() {
        Attributes parent = new Attributes();
        parent.add("otherKey", "otherVal");

        Attribute attribute = new Attribute("missingKey", "initialValue", parent);

        // parent is not null. 
        // parent.indexOfKey("missingKey") returns Attributes.NotFound
        // The if (i != Attributes.NotFound) block is skipped.
        // this.val is updated.
        // oldVal is parent.get("missingKey") which is null.

        try {
            attribute.setValue("newValue");
            fail("Should throw NPE because oldVal is null and passed to checkNotNull");
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testSetValue_SuccessfulUpdate() {
        Attributes parent = new Attributes();
        parent.add("key", "old");
        Attribute attr = new Attribute("key", "old", parent);

        // This covers: parent != null, index != NotFound, and updating both
        String result = attr.setValue("new");

        assertEquals("old", result);
        assertEquals("new", attr.getValue());
        assertEquals("new", parent.get("key"));
    }
}
